insert into practice_exercises (id, subject_name, level, title, source) values
  ('35e80836-3fd1-4d40-b77b-9dcadb46ad49', $$Natuurkunde$$, $$HAVO$$, $$Muziekdoos$$, $$HAVO Natuurkunde 2022-I$$),
  ('5678420b-3394-4a5f-9cf2-741b92b072b7', $$Natuurkunde$$, $$HAVO$$, $$New Horizons$$, $$HAVO Natuurkunde 2022-I$$),
  ('7d5cc8d1-7af1-4995-9ce0-ec283c6ee189', $$Natuurkunde$$, $$HAVO$$, $$Lithografie$$, $$HAVO Natuurkunde 2022-I$$),
  ('509ce376-29af-44b2-a447-1f54dcbef757', $$Natuurkunde$$, $$HAVO$$, $$Stunt in Dubai$$, $$HAVO Natuurkunde 2022-I$$),
  ('db2463bf-9e66-4bc1-87c9-77f876f8692c', $$Natuurkunde$$, $$HAVO$$, $$Exploderende draad$$, $$HAVO Natuurkunde 2022-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('738ed330-e54a-4fd7-a16f-596070a9b099', '35e80836-3fd1-4d40-b77b-9dcadb46ad49', $$figuur 1, 2 en 3 — muziekdoos met strips en rol; principe van het optillen door pinnen$$, $$natuurkunde-havo-2022-i-muziekdoos-context1.png$$, 496, $$Een muziekdoos is een klein muziekinstrument. Zie figuur 1 en 2.

figuur 1: foto van een muziekdoos in een hand, met de strips en de rol met pinnen aangewezen.
figuur 2: foto van een muziekdoos met opwindslinger, met de strips en de rol met pinnen aangewezen.

De muziekdoos maakt muziek door stalen strips te laten trillen. Op een draaiende, cilindervormige rol zijn pinnen aangebracht die een strip aan één uiteinde optillen. Zie figuur 3. De strip springt vervolgens los van de pin en begint te trillen.

figuur 3: schematische zijaanzichten van een strip die door een pin op de rol wordt opgetild — boven de uitgangssituatie (strip recht), onder het moment waarop de pin de strip omhoog buigt.

Door meerdere strips naast elkaar te gebruiken, kan een melodie worden gespeeld. Zie figuur 1 en 2.
De melodie herhaalt zich elke 15 seconde. In deze tijd roteert de rol dus één keer.$$, 'inline'),
  ('27108eb4-08ba-45c9-a26e-e30fbbf9b9cb', '35e80836-3fd1-4d40-b77b-9dcadb46ad49', $$figuur 4 — vier patronen (I t/m IV) van knopen en buiken in een trillende strip$$, $$natuurkunde-havo-2022-i-muziekdoos-context2.png$$, 496, $$De lengte van iedere strip is verschillend. Een strip gaat trillen in de grondtoon. In figuur 4 zijn vier patronen van knopen (K) en buiken (B) in een strip te zien.

figuur 4: vier tekeningen (I, II, III, IV) van een trillende strip, vastgezet aan het ene uiteinde en vrij bewegend bij de rol aan het andere uiteinde, elk met knopen (K) en buiken (B) op verschillende posities aangegeven.$$, 'inline'),
  ('a719e530-78af-42da-b31c-c2d427b37004', '35e80836-3fd1-4d40-b77b-9dcadb46ad49', $$figuur 5 — (u,t)-diagram van een trillende strip; muzieknoot a1 = 440 Hz$$, $$natuurkunde-havo-2022-i-muziekdoos-context3.png$$, 496, $$In tabel 15C van Binas en tabel 2.1c van Sciencedata is gegeven welke frequenties bij welke muzieknoten horen. Zo is te zien dat bij de muzieknoot a1 (ook wel a'' genaamd) een frequentie hoort van 440 Hz.
Met een camera is een opname gemaakt van een trillende strip. Hiermee is de uitwijking van de strip tegen de tijd bepaald. Het (u,t)-diagram hiervan staat in figuur 5.

figuur 5: (u,t)-diagram met u (mm) op de verticale as van −1,5 tot 1,5 en t (ms) op de horizontale as van 0 tot 10; een sinusvormig signaal met een amplitude van ongeveer 1,25 mm en ongeveer 4 volledige perioden zichtbaar tussen t = 0 en t = 10 ms.$$, 'inline'),
  ('81a5293c-9407-4077-a930-9d226c57db78', '35e80836-3fd1-4d40-b77b-9dcadb46ad49', $$definitie beeldfrequentie van een camera$$, $$natuurkunde-havo-2022-i-muziekdoos-context4.png$$, 496, $$De camera legt de trillende strip vast door er per seconde een bepaald aantal foto''s van te maken. Dit aantal foto''s per seconde is de zogenaamde beeldfrequentie.$$, 'inline'),
  ('1fc7b62c-df72-4a09-bdb4-2aec1c114745', '35e80836-3fd1-4d40-b77b-9dcadb46ad49', $$figuur 6 — strips van ''London Bridge'' en ''This Old Man''; zelfde rol, verschillende eindmassa$$, $$natuurkunde-havo-2022-i-muziekdoos-context5.png$$, 496, $$Een trillende strip werkt als een massa-veersysteem.
De strips kunnen aan het eind verzwaard worden door ze daar dikker te maken. De veerconstante van de strip verandert hierdoor niet, maar de toonhoogte verandert wel. De tonen van de liedjes ''London Bridge'' en ''This Old Man'' zijn bijna hetzelfde. Zie figuur 6.

figuur 6: foto van twee metalen strips naast elkaar met elk twee ronde gaten aan het verzwaarde uiteinde, gelabeld ''London Bridge'' en ''This Old Man''.

Voor beide liedjes wordt dezelfde rol met pinnen gebruikt. Er zit wel een verschil in de strips: één bepaalde strip van ''London Bridge'' geeft een lagere toon dan de vergelijkbare strip van ''This Old Man''.$$, 'inline'),
  ('d85095e6-f799-4c2a-b6b2-4b9d5a23ed0b', '35e80836-3fd1-4d40-b77b-9dcadb46ad49', $$uitwerkbijlage vraag 4 — twee zinnen met aan te kruisen alternatieven over beeldfrequentie en trilling$$, $$natuurkunde-havo-2022-i-muziekdoos-uitwerkbijlage-vraag4.png$$, 496, $$Uitwerkbijlage vraag 4: ''Om de tijdsduur van één volledige trilling van de strip met een fotocamera te bepalen, is meer dan / minder dan / precies één foto per trilling nodig.'' en ''De beeldfrequentie van de camera moet dan hoger zijn dan / lager zijn dan / gelijk zijn aan de frequentie van de trillende strip.'', met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('56ee4411-3f70-487b-b68f-8cfd1668f6ea', '5678420b-3394-4a5f-9cf2-741b92b072b7', $$opzet opgave (deel A/B) en figuur 1 — traject van New Horizons langs de baan van Jupiter naar Pluto$$, $$natuurkunde-havo-2022-i-new-horizons-context1.png$$, 496, $$Pluto is een dwergplaneet in ons zonnestelsel. Om Pluto te onderzoeken werd in januari 2006 de ruimtesonde New Horizons (NH) gelanceerd.

Deze opgave bestaat uit twee delen:
− deel A De reis van NH
− deel B De energievoorziening van NH

deel A De reis van NH

In figuur 1 is het traject van de ruimtesonde NH langs banen van planeten in het zonnestelsel weergegeven.

figuur 1: schema met de aarde in het midden, de cirkelvormige baan van Jupiter met daarop 12 genummerde posities, en de rechte lijn van het traject van NH die de baan van Jupiter bij positie 12 kruist en doorloopt naar Pluto; buiten de baan van Jupiter zijn nog drie bredere cirkelbanen van verdere planeten getekend.

Eén jaar na de lancering kruiste NH de baan van Jupiter. De afstand tussen NH en Jupiter was op dat moment heel klein. Door de aantrekkingskracht van Jupiter boog NH af richting Pluto. Jupiter heeft een omlooptijd van 12 jaar en beweegt in de richting van de pijl. De baan van Jupiter mag als cirkelvormig beschouwd worden. Op de baan zijn 12 posities van Jupiter aangegeven. Zie figuur 1.$$, 'inline'),
  ('631a1e8d-98a8-4112-8df4-b1b926ce03c8', '5678420b-3394-4a5f-9cf2-741b92b072b7', $$gegevens cirkelbaan om Pluto: m=465 kg, straal 12,5·10⁶ m, snelheid 2,6·10² m/s$$, $$natuurkunde-havo-2022-i-new-horizons-context2.png$$, 496, $$In juli 2015 was NH in de buurt van Pluto aangekomen. NH had toen een snelheid van 1,2·10⁴ m s⁻¹. De snelheid van Pluto wordt in deze opgave verwaarloosd.

De ontwerpers van de missie hadden de keuze uit drie opties:
1 NH wordt in een cirkelbaan om Pluto gebracht.
2 NH stort neer op Pluto.
3 NH passeert Pluto en gaat verder de ruimte in.

De ontwerpers hebben berekend welke snelheid nodig was om NH (m = 465 kg) in een baan met een straal van 12,5·10⁶ m om Pluto te laten cirkelen. Deze snelheid is 2,6·10² m s⁻¹.$$, 'inline'),
  ('62a4b816-1b58-4c6a-a042-770f51a1dfaf', '5678420b-3394-4a5f-9cf2-741b92b072b7', $$afremmen met hydrazine: 0,95 MJ arbeid per 1,0 kg brandstof$$, $$natuurkunde-havo-2022-i-new-horizons-context3.png$$, 496, $$Om NH af te remmen is een raket nodig. Deze raket gebruikt hydrazine als brandstof. De ontwerpers hebben berekend hoeveel hydrazine nodig zou zijn om NH af te remmen van 1,2·10⁴ m s⁻¹ tot 2,6·10² m s⁻¹. De raketmotor verricht 0,95 MJ arbeid per 1,0 kg gebruikte hydrazine.
De ontwerpers concludeerden dat NH veel meer massa aan brandstof nodig zou hebben dan zijn eigen massa van 465 kg.$$, 'inline'),
  ('233506a7-8d00-45d7-9dc7-387a969958d2', '5678420b-3394-4a5f-9cf2-741b92b072b7', $$overgang naar deel B en plutonium-238 als α-bron$$, $$natuurkunde-havo-2022-i-new-horizons-context4.png$$, 496, $$De ontwerpers hebben besloten om NH verder de ruimte in te sturen.

deel B De energievoorziening van NH

Voor de elektrische apparatuur aan boord van NH is een energiebron nodig. NH gebruikt hiervoor plutonium-238. Deze isotoop zendt alleen α-straling uit.$$, 'inline'),
  ('376a0bfd-7613-437e-87fb-852ffe1e2f3c', '5678420b-3394-4a5f-9cf2-741b92b072b7', $$figuur 2 — vervalkromme plutonium-238 met raaklijn op t=0; deeltjesmassa 3,95·10⁻²⁵ kg, activiteit 6,0·10¹⁵ Bq$$, $$natuurkunde-havo-2022-i-new-horizons-context5.png$$, 496, $$In figuur 2 staat de vervalkromme van plutonium-238 vanaf het moment van lanceren van NH. Op de verticale as staat het resterende percentage plutoniumdeeltjes ten opzichte van de lancering.
In het diagram is ook de raaklijn getekend op t = 0.

figuur 2: grafiek van het resterende percentage Pu-238 (%, 0-100) tegen de tijd t (jaar, 0-400); een dalende, naar boven gebogen kromme die geleidelijk afvlakt naar bijna 0% bij t=400 jaar, met een raaklijn getekend vanuit (0, 100%) die de horizontale as snijdt bij ongeveer t=120 jaar.

De ontwerpers moesten de massa van het Pu-238 berekenen waarmee de reactor van NH bij de lancering gevuld moest zijn. Voor de juiste werking moest de activiteit van het plutonium bij de lancering gelijk zijn aan 6,0·10¹⁵ Bq. De massa van een Pu-238-deeltje is gelijk aan 3,95·10⁻²⁵ kg.$$, 'inline'),
  ('a071a3cf-00d5-4551-a4fb-f391ad8b1ee6', '5678420b-3394-4a5f-9cf2-741b92b072b7', $$energie per vervallen kern (5,59 MeV) en elektrisch vermogen generator bij lancering (248 W)$$, $$natuurkunde-havo-2022-i-new-horizons-context6.png$$, 496, $$Per vervallende plutoniumkern komt 5,59 MeV energie vrij. Deze energie wordt volledig omgezet in warmte waarmee in een generator elektrische energie wordt opgewekt. Het elektrische vermogen van deze generator is bij de lancering van de missie 248 W. De activiteit van het plutonium bij de lancering is 6,0·10¹⁵ Bq.$$, 'inline'),
  ('09c5992d-ee51-4e5b-afd9-51b0a4cea4e1', '5678420b-3394-4a5f-9cf2-741b92b072b7', $$vermogen evenredig met activiteit; generator moet minimaal 31 W leveren$$, $$natuurkunde-havo-2022-i-new-horizons-context7.png$$, 496, $$Het elektrische vermogen is recht evenredig met de activiteit van het overgebleven plutonium.
Voor het goed functioneren van de apparatuur moet de generator minimaal 31 W leveren.$$, 'inline'),
  ('25aa6914-0de9-47ac-b242-308c3af25512', '5678420b-3394-4a5f-9cf2-741b92b072b7', $$uitwerkbijlage vraag 12 — herhaling van de vervalkromme van figuur 2 (leeg rooster) om de functioneerduur te bepalen$$, $$natuurkunde-havo-2022-i-new-horizons-uitwerkbijlage-vraag12.png$$, 496, $$Uitwerkbijlage vraag 12: dezelfde grafiek als figuur 2 — het resterende percentage Pu-238 (%, 0-100) tegen de tijd t (jaar, 0-400), met dezelfde dalende kromme — gevolgd door invulregels bij ''Bepaling:'' om de tijdsduur te berekenen waarin de energiebron van NH kan functioneren.$$, 'uitwerkbijlage'),
  ('e151d774-8f7e-4fd6-bd5d-887d7bd8a9bd', '7d5cc8d1-7af1-4995-9ce0-ec283c6ee189', $$artikel over printplaten, IC''s en lithografie; figuur 1 (printplaat), figuur 2 (IC), figuur 3 (belichten van een wafer, golflengte 193 nm)$$, $$natuurkunde-havo-2022-i-lithografie-context1.png$$, 496, $$Lees het volgende artikel.

In een elektrisch apparaat zitten onderdelen zoals weerstanden en diodes. Vroeger werden die onderdelen op een kunststof plaat met koperen geleiders bevestigd. Zo''n plaat wordt een printplaat genoemd. Zie figuur 1.

figuur 1: foto van een printplaat met diverse elektronische onderdelen (condensatoren, diodes, weerstanden) en koperen geleiderbanen.

Tegenwoordig worden printplaten vaak vervangen door ''integrated circuits'' (IC''s). Zie figuur 2.
In een IC zijn met behulp van licht microscopisch kleine patronen gemaakt. Deze patronen werken hetzelfde als onderdelen en geleiders op een printplaat, maar een IC is veel kleiner.

figuur 2: foto van een IC die met twee vingers wordt vastgehouden boven een printplaat.

IC''s worden met meerdere tegelijk gemaakt door een ronde plaat te ''belichten''. Zie figuur 3.
Dit proces heet lithografie. De IC''s worden daarna uit deze plaat gesneden.
Voor het belichten wordt een stralingsbron gebruikt met een golflengte van 193 nm.

figuur 3: foto van een persoon in cleanroomkleding die een ronde, glimmende wafer met daarop een patroon van IC''s vasthoudt.$$, 'inline'),
  ('161b3d71-c0b1-4543-a412-62a568f39031', '7d5cc8d1-7af1-4995-9ce0-ec283c6ee189', $$faseovergang van tin door laserpulsen; begintemperatuur 7·10² K$$, $$natuurkunde-havo-2022-i-lithografie-context2.png$$, 496, $$Om IC''s nog kleiner te maken is straling nodig met een kortere golflengte dan 193 nm. Om deze straling te maken schiet men met een laser pulsen op een kleine hoeveelheid tin. Door verhitting vindt een faseovergang van het tin plaats. Tijdens deze faseovergang zendt het tin straling uit waarmee de plaat wordt belicht.
Het tin heeft een begintemperatuur van 7·10² K en gaat over in de gasfase.$$, 'inline'),
  ('ac322adb-c9c0-416d-8f1b-0fb827abf4b8', '7d5cc8d1-7af1-4995-9ce0-ec283c6ee189', $$figuur 4 — (P,t)-diagram van laserpulsen; 1,5·10⁻⁴ J per puls, 2,5 J benodigd voor gasfase$$, $$natuurkunde-havo-2022-i-lithografie-context3.png$$, 496, $$In figuur 4 is een (P,t)-diagram gegeven van enkele pulsen van de laser waarmee het tin wordt beschoten.

figuur 4: (P,t)-diagram met P (W) op de verticale as van 0 tot 80 en t (μs) op de horizontale as van 0 tot 30; vier identieke, smalle pulsvormige pieken die elk oplopen tot een maximum van ongeveer 65 W, met tussenpozen van 8 μs tussen de toppen.

Tijdens één puls draagt de laser 1,5·10⁻⁴ J over op het tin.
Om de kleine hoeveelheid tin in de gasfase te krijgen moet er in korte tijd 2,5 J aan energie worden toegevoerd.$$, 'inline'),
  ('8de081c3-3dcf-4a69-9964-dfdbcbd7c7c1', '7d5cc8d1-7af1-4995-9ce0-ec283c6ee189', $$vergelijking oude (193 nm, 25 nm geleider) en nieuwe golflengte; fotonenergie 1,47·10⁻¹⁷ J$$, $$natuurkunde-havo-2022-i-lithografie-context4.png$$, 496, $$Met de oude golflengte van 193 nm konden geleiders worden gemaakt met een breedte van minimaal 25 nm.
De fotonen die worden uitgezonden door het tin hebben een energie van 1,47·10⁻¹⁷ J. Deze fotonen hebben een kleinere golflengte dan 193 nm.
Aangenomen wordt dat de minimale breedte van de geleiders (en daarmee het minimale formaat van IC''s) recht evenredig is met de golflengte van de gebruikte straling.$$, 'inline'),
  ('c30d0961-69ef-4684-bb20-beeea06b9858', '509ce376-29af-44b2-a447-1f54dcbef757', $$figuur 1 en 2 — katapult met steentje en de reuzenkatapult met platform en McDougall$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-context1.png$$, 496, $$Met een katapult kun je steentjes wegschieten. Zie figuur 1.
In Dubai heeft stuntman Chris McDougall zichzelf op een vergelijkbare manier vanaf de grond recht omhoog de lucht in geschoten. Hij gebruikte twee hijskranen als een soort reuzenkatapult. McDougall lag op een klein platform dat door de katapult werd versneld. Zie figuur 2.

figuur 1: foto van een hand die een katapult met een steentje vasthoudt, klaar om weg te schieten.
figuur 2: foto van twee hijskranen die samen als katapult fungeren, met het platform met McDougall onderaan bevestigd tussen de kabels.

De katapult oefende een grote kracht uit op het platform met McDougall. Hierdoor kreeg het platform met McDougall een grote versnelling in verticale richting. Op een bepaalde hoogte kwam hij los van het platform. Even na het bereiken van het hoogste punt opende hij een parachute om veilig te kunnen landen.$$, 'inline'),
  ('7bcf2f94-9dc4-4168-a5b0-fbf172d23035', '509ce376-29af-44b2-a447-1f54dcbef757', $$figuur 3 — vallend blok (27,5 ton) als energiebron; platform met McDougall (85 kg), 34 m, eindsnelheid 59 m/s$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-context2.png$$, 496, $$De energie voor de lancering werd geleverd door een groot blok. Tijdens het lanceren viel het blok (mblok = 27,5 ton) van een kleine hoogte op de grond. Zie figuur 3.

figuur 3: foto van een zwaar, met kettingen vastgezet blok gewicht (opgebouwd uit meerdere stalen platen van 5,5 ton) dat aan een kraan hangt.

Het blok viel over een afstand van 0,8 m. De energie van het blok werd gebruikt om het platform met McDougall (mtotaal = 85 kg) over een afstand van 34 m vanuit stilstand omhoog te versnellen. Op die hoogte verliet hij de katapult met een snelheid van 59 m s⁻¹.$$, 'inline'),
  ('8bd70123-8367-4911-9bd9-d5d89902c1e0', '509ce376-29af-44b2-a447-1f54dcbef757', $$figuur 4 — (h,t)-diagram (zonder schaalverdeling) met punten a t/m f van de stunt$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-context3.png$$, 496, $$Van de stunt is een videometing gemaakt.
In figuur 4 is de hoogte van McDougall tijdens het eerste deel van de stunt in een (h,t)-diagram weergegeven. In dit diagram zijn geen waardes langs de assen weergegeven.

figuur 4: (h,t)-diagram zonder schaalverdeling; de grafiek start in punt a bij h=0, loopt via punt b en punt c steil omhoog naar een maximum in punt d, en daalt vervolgens via punt e naar punt f.

Op de uitwerkbijlage staat een tabel met drie fases van de stunt.$$, 'inline'),
  ('2b54d658-036f-4172-b3b2-9c5bea4408ba', '509ce376-29af-44b2-a447-1f54dcbef757', $$figuur 5 — (v,t)-diagram eerste 5 seconden; vertraging na t=1,05 s groter dan g$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-context4.png$$, 496, $$Er is ook een (v,t)-diagram van de stunt gemaakt. Zie figuur 5.

figuur 5: (v,t)-diagram met v (m s⁻¹) op de verticale as van 0 tot 70 en t (s) op de horizontale as van 0 tot 5; de grafiek stijgt lineair vanaf v=0 bij t=0 tot een piek van ongeveer 59 m/s bij t≈1,05 s, en daalt vervolgens langs een naar boven gebogen kromme terug naar v=0 bij t=5 s.

In het diagram op de uitwerkbijlage zijn de eerste vijf seconden van de stunt weergegeven.
Nadat McDougall het platform op t = 1,05 s had verlaten, nam de snelheid van McDougall af met een vertraging groter dan de grootte van de valversnelling g.$$, 'inline'),
  ('1b64fe86-5df1-403d-bbb5-ab6679dab46c', '509ce376-29af-44b2-a447-1f54dcbef757', $$hoogte 125 m na 5,0 s; ontbrekend stuk (v,t)-diagram vanaf t=10 s door opengaan parachute$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-context5.png$$, 496, $$Na 5,0 s bereikte McDougall een hoogte van 125 m en begon de val naar beneden. Even later trok McDougall zijn parachute open voor het laatste deel van de val tot de (veilige) landing. Van dit deel van de val ontbreekt in het (v,t)-diagram op de uitwerkbijlage het stuk vanaf t = 10 s.$$, 'inline'),
  ('ca243919-b66b-475e-8f47-5e9911a76764', '509ce376-29af-44b2-a447-1f54dcbef757', $$vermelding van de tabel met vier fasen van de hele stunt op de uitwerkbijlage$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-context6.png$$, 496, $$Op de uitwerkbijlage staat een tabel die betrekking heeft op vier fasen van de hele stunt.$$, 'inline'),
  ('1555e9dd-a2ac-4760-9a37-5ae977f6e13a', '509ce376-29af-44b2-a447-1f54dcbef757', $$uitwerkbijlage vraag 18 — tabel om per fase het punt in de grafiek (a t/m f) te omcirkelen$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-uitwerkbijlage-vraag18.png$$, 496, $$18 Omcirkel in de tabel per fase met welk punt in de grafiek (a, b, c, d, e of f) deze fase overeenkomt.

Tabel met de fases ''McDougall komt los van de katapult.'', ''McDougall bereikt het hoogste punt.'' en ''McDougall opent zijn parachute.'', met bij elke fase de keuzemogelijkheden a, b, c, d, e en f om te omcirkelen.$$, 'uitwerkbijlage'),
  ('8f5f7002-9de1-42fe-a6b0-3b6fe7300b3f', '509ce376-29af-44b2-a447-1f54dcbef757', $$uitwerkbijlage vraag 19 — (v,t)-diagram (0-5 s) met invulruimte voor bepaling en antwoord$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-uitwerkbijlage-vraag19.png$$, 496, $$19 (v,t)-diagram met v (m s⁻¹) op de verticale as van 0 tot 70 en t (s) op de horizontale as van 0 tot 5; dezelfde grafiek als figuur 5, met een piek van ongeveer 59 m/s bij t≈1,05 s, gevolgd door invulregels bij ''−Bepaling:'' en ''−Antwoord:'' om de versnelling direct na het verlaten van het platform te bepalen.$$, 'uitwerkbijlage'),
  ('602f2e9f-8fd8-4849-ab95-89691b3b8831', '509ce376-29af-44b2-a447-1f54dcbef757', $$uitwerkbijlage vraag 20 — uitgebreid (v,t)-diagram tot t=22 s om het verdere verloop in te tekenen$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-uitwerkbijlage-vraag20.png$$, 496, $$20 (v,t)-diagram met v (m s⁻¹) op de verticale as van −20 tot 60 en t (s) op de horizontale as van 0 tot 22; de bekende grafiek van t=0 tot ongeveer t=7,5 s (piek bij t≈1,05 s, dalend tot een minimum van ongeveer −20 m s⁻¹ bij t≈7,5 s), gevolgd door een kort stijgend lijnstuk tot ongeveer t=10 s waarna het diagram leeg is zodat de leerling het verdere verloop tot de landing kan intekenen.$$, 'uitwerkbijlage'),
  ('d655ae5d-eb4c-4258-a5a5-b94f072765f1', '509ce376-29af-44b2-a447-1f54dcbef757', $$uitwerkbijlage vraag 21 — tabel om per fase de richting van de resulterende kracht te omcirkelen$$, $$natuurkunde-havo-2022-i-stunt-in-dubai-uitwerkbijlage-vraag21.png$$, 496, $$21 Geef in de tabel per fase door omcirkelen aan of de resulterende kracht op McDougall op dat moment naar boven gericht was, naar beneden gericht was of gelijk was aan 0 N.

Tabel met de fases ''McDougall wordt versneld door de katapult.'', ''McDougall is op het hoogste punt.'', ''McDougall daalt met constante snelheid.'' en ''McDougall wordt afgeremd door de grond.'', met bij elke fase de keuzemogelijkheden ''naar boven gericht'', ''gelijk aan 0 N'' en ''naar beneden gericht'' om te omcirkelen.$$, 'uitwerkbijlage'),
  ('c886e8d3-a0e7-42b7-88d6-3d401339fd0c', 'db2463bf-9e66-4bc1-87c9-77f876f8692c', $$figuur 1 — kunstmatige bliksem (80 m) tijdens Glow Eindhoven; koperdraad R=35 Ω, haar-diameter 0,060 mm$$, $$natuurkunde-havo-2022-i-exploderende-draad-context1.png$$, 496, $$In 2016 werd in Eindhoven tijdens het festival Glow voor publiek kunstmatig een ''bliksem'' met een recordlengte van 80 m gemaakt. Zie figuur 1.

figuur 1: nachtfoto van het festivalterrein met een felle, rechte lichtstreep (de kunstmatige bliksem) die over een lange afstand tussen gebouwen door loopt, met publiek in de verte.

Voor het opwekken van de bliksem werd een dunne draad van koper gebruikt met een weerstand van 35 Ω. De draad was 80 m lang. Een menselijke haar heeft een diameter van 0,060 mm. Zowel de draad als een mensenhaar is cilindervormig.$$, 'inline'),
  ('fc6e3046-4610-43c4-a83b-f539e685251c', 'db2463bf-9e66-4bc1-87c9-77f876f8692c', $$hoge spanning, vermogen 7,1·10⁹ W; formule P=U²/R$$, $$natuurkunde-havo-2022-i-exploderende-draad-context2.png$$, 496, $$Om de bliksem op te wekken werd de draad op een hoge spanning aangesloten. Hierdoor ging een grote stroom door de draad lopen. Er werd een enorm vermogen van 7,1·10⁹ W in de draad ontwikkeld. Neem aan dat de weerstand van de draad tijdens dit proces constant was.
Voor het vermogen dat in de draad wordt omgezet geldt:

P = U²/R$$, 'inline'),
  ('418b8257-e427-461c-b64b-d5077b62e941', 'db2463bf-9e66-4bc1-87c9-77f876f8692c', $$weerstand van de draad neemt toe met de temperatuur$$, $$natuurkunde-havo-2022-i-exploderende-draad-context3.png$$, 496, $$Tijdens dit proces bleef de weerstand van de draad echter niet constant. De weerstand nam toe met de temperatuur.$$, 'inline'),
  ('220d713f-7a5d-454d-895c-00726770f143', 'db2463bf-9e66-4bc1-87c9-77f876f8692c', $$vergelijking met opladen smartphone: 1,4·10⁻⁵ s, 7,1·10⁹ W, accu 9,88 Wh$$, $$natuurkunde-havo-2022-i-exploderende-draad-context4.png$$, 496, $$Iemand vraagt zich af of voor het opwekken van deze bliksem veel energie nodig was. Hij vergelijkt het met het opladen van een smartphone.
De draad leverde gedurende 1,4·10⁻⁵ s een vermogen van 7,1·10⁹ W. Een gewone smartphone accu heeft een capaciteit van 9,88 Wh.$$, 'inline'),
  ('c6faf55e-dabd-402d-a959-a8c010bafdf8', 'db2463bf-9e66-4bc1-87c9-77f876f8692c', $$snelle energietoevoer laat de draad exploderen in kleine koperdruppels; knal vergelijkbaar met donder$$, $$natuurkunde-havo-2022-i-exploderende-draad-context5.png$$, 496, $$Het toevoeren van de energie verliep zó snel dat de draad explodeerde. Hierbij ontstonden kleine druppels koper. Het publiek hoorde deze explosie als een knal vergelijkbaar met de donder bij een bliksem.$$, 'inline'),
  ('1c9f14ba-1c47-44e4-9d8e-2dac8f0511ae', 'db2463bf-9e66-4bc1-87c9-77f876f8692c', $$figuur 2 — uitvergroot deel van figuur 1; druppels met 0,9 km/s, verdampen binnen 1,0·10⁻⁴ s$$, $$natuurkunde-havo-2022-i-exploderende-draad-context6.png$$, 496, $$De hete druppels vlogen met een snelheid van 0,9 km s⁻¹ weg in de richting van het publiek achter de hekken. Binnen 1,0·10⁻⁴ s verdampten de druppels.
Een gedeelte van figuur 1 staat vergroot in figuur 2.

figuur 2: uitvergrote nachtfoto van een deel van de lichtstreep (de bliksem) tussen een lantaarnpaal en het hek waarachter het publiek staat te kijken.$$, 'inline');

