  ('2eb45c50-ab6d-42da-b48b-f75faf166c12', '509ce376-29af-44b2-a447-1f54dcbef757', 19,
   $$[{"domain": "Beweging en energie", "subdomain": "Kracht en beweging"}]$$::jsonb,
   $$["raaklijn", "versnelling bepalen", "(v,t)-diagram", "luchtweerstandskracht"]$$::jsonb,
   $$Bepalen van een versnelling uit de raaklijn aan een (v,t)-diagram en verklaren van extra vertraging door luchtweerstand.$$,
